Lemma star_syscall_nil : forall ms model x8 eff model',
  m_halted model = None ->
  ms_svc_pending ms = Some x8 ->
  syscall_spec (sys_input segs ms x8) model (Ok eff model' []) ->
  m_halted model' = None ->
